/**
 * CoolProp WASM JavaScript Wrapper - Main Entry Point
 * 
 * This file provides the main entry point for the CoolProp WASM module,
 * offering both CommonJS and ES Module compatibility.
 */

// Import the WASM module
import Module from './coolprop.js';

/**
 * Initialize CoolProp WASM module
 * @returns {Promise<Object>} The initialized CoolProp module
 */
export async function initCoolProp() {
    return await Module();
}

/**
 * Default export for convenience
 */
export default initCoolProp;

/**
 * CommonJS compatibility
 */
if (typeof module !== 'undefined' && module.exports) {
    module.exports = initCoolProp;
    module.exports.initCoolProp = initCoolProp;
    module.exports.default = initCoolProp;
}